corrected_code:
const resolveTicketAttachment = async (req, res, next) => {
  const attachment = await AttachmentModel.findOne({ _id: req.params.attachId, ticketId: req.params.ticketId });
  if (!attachment) return res.status(404).send('Attachment not found');
  const ticket = await TicketModel.findOne({ _id: req.params.ticketId, customerId: req.user.id });
  if (!ticket && !req.user.isSupportStaff) return res.status(403).send('Access denied to ticket attachment');
  req.locals = { attachment };
  next();
};

app.get('/api/tickets/:ticketId/attachments/:attachId', tokenAuth, resolveTicketAttachment, (req, res) => {
  res.download(req.locals.attachment.filePath, req.locals.attachment.originalFilename);
});
